package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"fmt"
	"io"
	"net/http"
	"sync"
	"time"

	"golang.org/x/crypto/scrypt"
)

type CreditPool struct {
	mu       sync.Mutex
	balances map[string]int64
	pending  map[string]int64
}

type EmailRecord struct {
	To        string
	Body      []byte
	Timestamp time.Time
	Credits   int64
}

var pool = &CreditPool{
	balances: make(map[string]int64),
	pending:  make(map[string]int64),
}

var emailStore = struct {
	mu      sync.Mutex
	records []EmailRecord
}{}

// Fixed application salt for key derivation. A per-user random salt stored
// alongside ciphertext would be preferable, but scrypt with a salt already
// provides proper key stretching against brute-force attacks.
var kdfSalt = []byte("email-service-kdf-salt-v1")

func deriveKey(passphrase string) ([]byte, error) {
	// scrypt parameters: N=32768, r=8, p=1, 32-byte key for AES-256.
	return scrypt.Key([]byte(passphrase), kdfSalt, 32768, 8, 1, 32)
}

func encryptBody(plaintext []byte, key []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	return gcm.Seal(nonce, nonce, plaintext, nil), nil
}

func (cp *CreditPool) GetBalance(user string) int64 {
	cp.mu.Lock()
	defer cp.mu.Unlock()
	return cp.balances[user]
}

func (cp *CreditPool) Deposit(user string, amount int64) {
	cp.mu.Lock()
	defer cp.mu.Unlock()
	cp.balances[user] += amount
}

func (cp *CreditPool) SpendCredits(user string, amount int64) bool {
	cp.mu.Lock()
	defer cp.mu.Unlock()
	if cp.balances[user] < amount {
		return false
	}
	cp.balances[user] -= amount
	return true
}

func processEmailBatch(user string, recipients []string, body string, key []byte) error {
	creditCost := int64(len(recipients))

	if !pool.SpendCredits(user, creditCost) {
		return fmt.Errorf("insufficient credits")
	}

	for _, r := range recipients {
		encBody, err := encryptBody([]byte(body), key)
		if err != nil {
			// Refund on failure
			pool.Deposit(user, creditCost)
			return err
		}
		emailStore.mu.Lock()
		emailStore.records = append(emailStore.records, EmailRecord{
			To:        r,
			Body:      encBody,
			Timestamp: time.Now(),
			Credits:   1,
		})
		emailStore.mu.Unlock()
	}

	return nil
}

func handleSendEmail(w http.ResponseWriter, r *http.Request) {
	user := r.Header.Get("X-User-ID")
	if user == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	recipients := r.URL.Query()["to"]
	body := r.URL.Query().Get("body")
	passphrase := r.Header.Get("X-Encryption-Key")

	if len(recipients) == 0 || body == "" || passphrase == "" {
		http.Error(w, "missing parameters", http.StatusBadRequest)
		return
	}

	if len(recipients) > 100 {
		http.Error(w, "too many recipients", http.StatusBadRequest)
		return
	}

	key, err := deriveKey(passphrase)
	if err != nil {
		http.Error(w, "key derivation failed", http.StatusInternalServerError)
		return
	}

	if err := processEmailBatch(user, recipients, body, key); err != nil {
		http.Error(w, err.Error(), http.StatusPaymentRequired)
		return
	}

	w.WriteHeader(http.StatusOK)
	// Do not leak any derived key material in the response.
	fmt.Fprintf(w, "sent %d emails", len(recipients))
}

func handleDeposit(w http.ResponseWriter, r *http.Request) {
	user := r.Header.Get("X-User-ID")
	if user == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}
	pool.Deposit(user, 10)
	fmt.Fprintf(w, "deposited 10 credits")
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/send", handleSendEmail)
	mux.HandleFunc("/deposit", handleDeposit)

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadTimeout:       10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
	}
	srv.ListenAndServe()
}
